import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"VISTA: Generative Visual Imagination for Vision-and-Language Navigation","description":"","frontmatter":{"title":"VISTA: Generative Visual Imagination for Vision-and-Language Navigation","arxiv":"2505.07868","date":"2025-05-09","authors":"Yanjia Huang, Mingyang Wu, Renjie Li, Zhengzhong Tu","categories":"cs.RO","topics":"具身智能, 视觉语言导航, 生成式想象","outline":[2,2]},"headers":[],"relativePath":"papers/2505.07868.md","filePath":"papers/2505.07868.md","lastUpdated":null}'),l={name:"papers/2505.07868.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="vista-generative-visual-imagination-for-vision-and-language-navigation" tabindex="-1">VISTA: Generative Visual Imagination for Vision-and-Language Navigation <a class="header-anchor" href="#vista-generative-visual-imagination-for-vision-and-language-navigation" aria-label="Permalink to &quot;VISTA: Generative Visual Imagination for Vision-and-Language Navigation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2505.07868" target="_blank" rel="noreferrer">2505.07868</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-05-09</td></tr><tr><td><strong>作者</strong></td><td>Yanjia Huang, Mingyang Wu, Renjie Li, Zhengzhong Tu</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>让导航智能体先用扩散模型&quot;想象&quot;出目标场景的图像，再用一个对齐滤波器把想象与当前观测比对成注意力图，最后把这张图转成文字描述喂给 LLaMA2 做链式推理选动作。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv abs 页给出的 HTML 版本是 <strong>v2</strong>（2025-05-17 修订，v1 为 2025-05-09），本文按 v2 全文撰写。注意与 <a href="/notes/papers/2510.15831">2510.15831</a> 的 VISTA（视频生成的自改进智能体框架）同名但不是同一篇工作。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视觉语言导航（VLN）的主流范式是&quot;观察-推理&quot;：智能体在每个节点看一圈全景，结合指令与历史决定下一步走向哪个候选视角。这套范式在短程指令上已经做得不错，但在长时程场景里有个结构性缺陷——决策只能建立在<strong>当前可见</strong>的信息上。指令说&quot;去厨房拿一罐苏打水&quot;，而厨房不在视野里，智能体就只能靠&quot;哪个方向看起来更像通往厨房&quot;这种弱信号做局部预测，错误一旦发生就会沿轨迹累积。</p><p>本文的立场是：人类导航时会先在脑子里想象目标场景长什么样，再拿这个想象去比对眼前的画面。把这一步显式建模出来——用预训练扩散模型生成目标场景图像，再把它与当前观测对齐——就能给决策提供一个超出当前视野的前瞻信号。这个问题重要，是因为它触及了&quot;生成模型能否为决策提供有用先验&quot;这一更一般的命题；如果想象出来的图像只是好看而不可用，那么整条把生成模型塞进控制回路的路线就要重新评估。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>VLN 主线</strong>：EnvDrop、PREVALENT、RecBERT、HAMT、DUET 一路把跨模态预训练与拓扑图规划做到 R2R val-unseen 的 63–71.5 SR。它们的共同点是决策完全基于已观测到的视觉特征。</p><p><strong>VLN 里的视觉想象</strong>：Pathdreamer 用 GAN 从视觉历史幻觉出全景，但输出只服务于启发式搜索，没有接进策略；PanoGen 与 DiffPano 用扩散模型外推目标视角；PanoGen++ 进一步用 LoRA 微调与结构化 inpainting 适配室内导航。本文对这一族的批评是精确的：它们<strong>离线生成</strong>，且把想象内容当作辅助信息（通常是数据增广），而不是决策回路里的核心组件。</p><p><strong>CoT 推理</strong>：NavGPT、MapGPT、NaviLLM 把 LLM 当作导航骨干；C-Instructor、InstructNav、NavCoT 把链式推理引入导航。这些工作的推理链是纯文本的——视觉被先转成文字描述再送进 LLM，视觉与语言之间的落地（grounding）没有被显式约束。NavCoT 在本文表中只有 40.23 SR，说明可训练 CoT 这条路当时远未跑通。</p><p>三条线各自缺一块：想象没有接进决策，推理没有视觉落地，主线方法没有前瞻。VISTA 的设计正是把这三块串起来。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>顺着当时已有的东西可以这样推。首先，LoRA 微调的 Stable Diffusion 已经能在 MP3D 这类室内数据上生成风格合理的房间图像，PanoGen++ 证明了这一点。其次，Grounded-SAM 能把文本短语落到图像区域上，这提供了一种<strong>免人工标注</strong>的伪监督来源。第三，LLaMA2 + LoRA 已经能被微调成输出结构化推理链。</p><p>于是缺的那一环是：想象出来的图像和当前观测是两张不同的图，怎么让它们发生关系？最直接的答案是学一个跨视图的对齐模块，输出一张空间注意力图——它既是&quot;想象是否成真&quot;的验证信号，也是&quot;该往哪儿看&quot;的指示。而这张注意力图恰好可以被文字化（&quot;掩码高亮了走廊左侧&quot;）后塞进 CoT 的中间步，从而让语言推理有视觉依据。</p><p>还剩一个工程问题：什么时候该按指令想象（静态模式）、什么时候该按当前观测想象（动态模式）？在不确定性高的时候依赖指令更稳，在指令模糊时依赖观测更准——于是需要一个基于轨迹不确定度与视觉-语义相似度的调度器。三个模块由此闭合。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>局部预测之所以在长时程上崩，是因为&quot;下一步该走哪&quot;这个决策的信息源只有当前视野，而目标在视野之外。把目标先渲染成一张图像，就把一个模糊的语言目标转成了一个可以逐像素比对的视觉模板；比对结果（注意力图）再把决策从&quot;猜方向&quot;变成&quot;找匹配区域&quot;。生成模型在这里不是为了画得好看，而是为了把语言目标搬进与观测同一个空间，使二者可比。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以指令&quot;go to the kitchen and grab a soda&quot;、当前站在客厅为例：</p><ol><li><strong>自适应想象调度器（AIS）</strong>：计算轨迹不确定度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（由动作熵与路径偏离度构成）与视觉-语义相似度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（想象图与观测图 embedding 的余弦相似度），按阈值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">u</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 在静态（指令驱动）与动态（观测驱动）两种模式间切换。静态模式用语言模型从指令里抽出语义实体（&quot;kitchen&quot;、&quot;stairs&quot;、&quot;sofa&quot;）；动态模式用轨迹历史与当前观测提出即时目标。</li><li><strong>视觉想象模块</strong>：先用 Qwen2-VL 把候选场景描述成一句话（&quot;A spacious living room with a blue sofa, wooden floors, and large windows.&quot;），再把这句话送进 LoRA 微调的 Stable Diffusion v1.5 生成想象图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0883em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.453em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">SD</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span>；同时把当前观测的掩码区域用同一描述引导 inpaint，得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1942em;vertical-align:-0.2458em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9484em;"><span style="top:-2.4542em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">inpaint</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2458em;"><span></span></span></span></span></span></span></span></span></span>。</li><li><strong>感知对齐滤波器（PAF）</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0883em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.453em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">SD</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1942em;vertical-align:-0.2458em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9484em;"><span style="top:-2.4542em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">inpaint</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2458em;"><span></span></span></span></span></span></span></span></span></span> 经共享 ResNet-18 编码后用多头注意力融合，解码成空间注意力图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0913em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose"><span class="mclose">]</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">W</span></span></span></span></span></span></span></span></span></span></span></span>。</li><li><strong>导航链式推理</strong>：把指令、观测描述、注意力图的文字摘要、导航历史组织成结构化 prompt，送进 LoRA 微调的 LLaMA2-7B，按&quot;目标落地 → 感知验证 → 决策辩护&quot;三段输出推理链与最终动作。</li></ol><p>训练侧：PAF 用 3 万条四元组 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1984em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.453em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">SD</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9484em;"><span style="top:-2.4542em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">inpaint</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2458em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">GT</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 训练，伪真值掩码由 Qwen 抽取的实体关键词经 Grounded-SAM 定位得到，损失为 BCE + soft Dice，Adam、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">256</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">256</span></span></span></span>、50 epoch 早停。SD 的 LoRA 用 MP3D 的 5k 对目标-描述样本训练，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>、50 epoch、2×A100 80GB 约 18 小时。附带产出一个 R2R-Imagine 数据集，超过 25 万张 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">256</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">256</span></span></span></span> 想象图。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>模式选择写成阈值判据（HTML 版该式渲染有断裂，此处按正文文字描述表述）：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 分别越过阈值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">u</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 时取 static，否则取 dynamic。注意力图由</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.8em;vertical-align:-0.65em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mopen"><span class="delimsizing size2">(</span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen"><span class="delimsizing size1">(</span></span><span class="mord mathnormal">ϕ</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ϕ</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-2.453em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">SD</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ϕ</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9484em;"><span style="top:-2.4542em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">inpaint</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2458em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mclose"><span class="delimsizing size1">)</span></span><span class="mclose"><span class="delimsizing size2">)</span></span></span></span></span></span></p><p>给出，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ϕ</span></span></span></span> 是共享 ResNet-18，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是多头注意力融合 + 解码，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span></span></span></span> 是逐像素 sigmoid。</p><p>这里值得对数学基础较弱的读者点明一件事：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的监督来自 Grounded-SAM 在<strong>当前观测</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 上定位实体关键词得到的掩码。也就是说，训练目标本质是&quot;在当前画面里找出描述中提到的物体&quot;——这是一个<strong>开放词表检测</strong>任务，而不是&quot;验证想象是否成真&quot;。想象图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0883em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.453em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">SD</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span> 与 inpaint 图只是这个检测器的额外输入通道。这个观察对理解全文的机制很关键：PAF 的监督信号里不含任何&quot;目标在视野外时该指向哪里&quot;的信息，因为当目标不在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 中时，Grounded-SAM 给不出有意义的掩码。论文未讨论这类样本在 3 万条四元组中如何处理。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：在标准 VLN 基准上是否有效？</strong> R2R（MP3D，90 个场景、10,567 个全景点、7,189 条轨迹）。Val-Unseen 上 VISTA 得 SR 77.8、SPL 68.3、NE 2.92、TL 13.26；Test-Unseen 得 SR 74.9、SPL 66.7、NE 3.77、TL 14.20。</p><p>这里有几处需要按表核对而非按文字采信。摘要写&quot;R2R 上 SR +3.6%&quot;，正文写&quot;相对此前最好的 DUET-Imagine 提升 +3.2% SR、+7.5 SPL&quot;。按表算：DUET-Imagine val-unseen SR 是 72.12，差值是 <strong>5.68</strong>；而 val-unseen 上 SR 最高的基线其实是 PanoGen 的 74.2，差值恰好 <strong>3.6</strong>。SPL 侧同理：相对 DUET-Imagine 的 60.48 差 <strong>7.82</strong>，相对 PanoGen 的 64.3 差 4.0。因此&quot;+3.6%&quot;对应的是 PanoGen 而非 DUET-Imagine，正文表述与表格不一致。此外正文称&quot;在 SR、SPL、NE 上全面超过既有模型&quot;，但 <strong>Test-Unseen 的 NE 3.77 明显差于 PanoGen 的 3.31、DUET-Imagine 的 3.52 与 DUET 的 3.65</strong>——只有 SR 与 SPL 成立。</p><p><strong>问题二：能否迁移到别的导航设定？</strong> RoboTHOR 上 VISTA 得 SWPL 28.8、SR 43.1，对比 ESC 的 22.2/38.1、VLTNet 的 17.1/33.2、OWL 的 17.2/27.5。</p><p><strong>问题三：各模块贡献？</strong> Val-Unseen 消融：完整 77.8/68.3、去想象 66.7/61.0、去对齐滤波 68.3/62.1、去 AIS 73.4/63.0、去 CoT 71.5/64.4。想象模块的贡献最大（−11.1 SR），对齐滤波次之（−9.5），CoT 与 AIS 较小。</p><p>需要指出一处：正文写&quot;我们通过 RoboTHOR 进一步分析模块作用，视觉想象在长路径（&gt;15m）上显著提升 SR +11.1%&quot;，而 <strong>+11.1 恰好等于 R2R val-unseen 上完整模型与去想象变体的差（77.8−66.7）</strong>，且论文没有给出任何 RoboTHOR 的分路径长度表。这更可能是复制错误而非独立结论。</p><p><strong>失败模式</strong>（作者自述）：想象与真实环境偏差过大导致对齐误导决策；注意力掩码在杂乱场景中过宽或错位；AIS 在高度模糊环境里过早选静态模式而忽略实时视觉线索。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：VISTA 把&quot;想象-对齐&quot;引入 VLN 决策回路，用 LoRA 微调的 SD 生成目标场景图，用一个跨视图对齐滤波器把它变成注意力图，再把注意力图文字化后送进 LLaMA2 做三段式链式推理。R2R val-unseen 达到 SR 77.8、SPL 68.3，RoboTHOR 达到 SR 43.1。消融显示想象模块贡献最大（−11.1 SR），CoT 与调度器较小。但正文中的多处提升幅度与表格对不上，且 Test-Unseen 的导航误差实际差于 PanoGen 与 DUET-Imagine。全部评测在仿真中完成。</p><p><strong>3 句话版</strong>：把语言目标先渲染成图像，再与当前观测对齐成注意力图，把 VLN 的决策依据从&quot;当前视野&quot;扩展到&quot;预期目标&quot;。R2R val-unseen SR 77.8，消融中想象模块单项值 11.1 分。方法的效率与部分数值报告存在明显问题。</p><p><strong>1 句话版</strong>：用扩散模型把语言目标画出来，再让智能体在眼前的画面里找它。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条不是方法论而是<strong>可行性</strong>：论文同时声称&quot;想象场景在线用 LoRA 微调的 SD 生成&quot;（结论段与 §3.2）与&quot;推理平均 8 FPS（含视觉想象与 CoT 推理）&quot;（§4.1），而 §4.1 又写明单张想象图在 A100 上需要 <strong>4.2 秒</strong>。这三条不可能同时为真——4.2 s/张对应 0.24 FPS，比 8 FPS 慢约 33 倍，而这还没算 LLaMA2-7B 的 CoT 解码。</p><p>有两种自洽读法，论文都没有明说。其一：想象图其实是离线预生成的（这与 R2R-Imagine 这个&quot;覆盖所有 R2R 划分、25 万张图&quot;的数据集的存在高度吻合——25 万张 × 4.2 s ≈ 292 GPU 小时，明显是离线批处理的产物）。若如此，则本文与它所批评的 PanoGen/PanoGen++ 的&quot;离线生成&quot;在部署形态上并无本质差别，&quot;闭环在线想象&quot;的叙事需要撤回。其二：8 FPS 只统计了 CoT 之外的某个子模块。无论哪种，&quot;实用可行性&quot;这一主张目前没有证据支撑。</p><p>同一处还有一个更隐蔽的问题：§3.2 说被描述的候选场景&quot;来自训练数据或先前的想象&quot;。若测试时使用了来自训练数据的候选场景，则存在信息泄漏；论文对此未作澄清。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且只需推理：取一个公开的 R2R 智能体（如 DUET）作为动作策略，把 VISTA 的&quot;想象&quot;通道替换成三种对照送进同一个 PAF + CoT 栈——(a) 真实想象图（LoRA-SD 生成）、(b) 从<strong>其他 episode</strong> 随机抽的想象图（语义无关但风格一致）、(c) 纯高斯噪声图。三者共用同一份 PAF 权重，无需重训。</p><p>判据非常直接：如果 (b) 与 (a) 的 SR 差距很小，说明 PAF 实际上在做&quot;用文本关键词在当前观测里做开放词表检测&quot;，想象图只提供了风格先验而非目标信息——这与 §6 中对 PAF 监督信号的分析一致；此时 11.1 分的想象增益应当被重新归因给&quot;引入了一个基于 Grounded-SAM 伪标签训练的检测模块&quot;。如果 (b) 显著劣于 (a) 而 (c) 更差，则想象内容确实携带任务信息，本文的机制解释成立。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的替代解释是：<strong>VISTA 的收益来自把一个开放词表检测器接进了决策回路，而不是来自&quot;想象&quot;</strong>。支持这个解释的三条证据都在论文自己的材料里。第一，PAF 的伪真值完全由 Grounded-SAM 在当前观测上生成，训练目标就是检测。第二，消融里&quot;去掉对齐滤波&quot;（−9.5）与&quot;去掉想象&quot;（−11.1）的幅度接近，而这两者共享同一条信息通路——若想象独立有效，二者的效应量应当可分离。第三，CoT 侧的输入是注意力图的<strong>文字摘要</strong>（&quot;掩码高亮了走廊左侧&quot;），这条通路能传递的信息量极小，基本等价于一个方向性提示。</p><p>判决实验：把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0883em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.453em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">SD</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1942em;vertical-align:-0.2458em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9484em;"><span style="top:-2.4542em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">inpaint</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2458em;"><span></span></span></span></span></span></span></span></span></span> 两路输入从 PAF 中整个移除，只保留 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与文本关键词，重训一个同架构的检测器（即一个轻量的开放词表 grounding 模块），其余流程不变。如果 SR 回到 75 以上，则&quot;生成式想象&quot;的必要性被证伪，本文实际上是一篇&quot;把 grounding 接进 CoT 导航&quot;的工作。</p><p>第二个攻击面是评测覆盖。表中最强的基线是 PanoGen（74.2 SR），而 2023–2024 年 R2R 上还有若干以大规模环境增广预训练为主的系统未被纳入（本文未列出这些系统，其具体分数我未在文中核实，故不引用数字）。在只与这一组基线比较的前提下声称 &quot;new state-of-the-art&quot; 需要保留。</p><p>第三，Test-Unseen 上 TL 从 13.26 涨到 14.20、NE 从 2.92 涨到 3.77，而 SR 只掉 2.9——这个组合意味着在未见环境里智能体走得更远、停得更偏却仍常常落在 3 米阈值内，提示 SR 与 NE 在该设定下可能被&quot;绕路后碰巧接近&quot;这类行为拉开，值得用更严的成功阈值复核。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>本文把想象当作<strong>一次性的目标模板</strong>：生成一张图、比对一次、丢掉。但生成模型真正独特的能力不是画一张图，而是能刻画一个<strong>分布</strong>——同一句&quot;厨房&quot;在不同房子里长得完全不同，而这种分散程度本身就是信息：如果模型对目标外观极度不确定，那就说明当前指令在当前环境里还不足以确定目标，智能体应当去收集更多信息而不是急着走。</p><p>非增量的重新 framing 是：<strong>把想象的方差当作探索信号，把导航变成一个主动降低目标不确定性的过程</strong>。具体地，对同一条件采样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 张想象图，用它们在 PAF 输出空间中的分散度作为目标不确定性 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0993em;">U</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0993em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>；策略的目标从&quot;最大化朝目标的进展&quot;改为&quot;最大化进展 − <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0993em;">U</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0993em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的期望下降&quot;，即优先走那些能让想象收敛的分支（例如先走到走廊尽头看清房间类型，再决定进哪扇门）。这同时给 AIS 提供了一个有原则的替代——不再靠两个手工阈值，而是由不确定性直接驱动模式切换（论文的 Limitations 恰好把手工阈值列为局限）。</p><p>可借鉴的相邻领域工具是主动感知与信息增益规划（information-gathering POMDP），以及扩散模型不确定性量化里用多样本分歧估计 epistemic uncertainty 的做法。第一个实验不需要新模型：在现有 R2R-Imagine 数据上，对每个决策点采 8 张想象图，检验 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0993em;">U</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0993em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是否与该步的动作正确性显著负相关。若相关性成立，这个量就可以零成本地接进现有 CoT prompt 作为一个新的中间步——而且它顺带解决了 §9 指出的效率问题：多采样只需在<strong>少数高不确定点</strong>触发，而不是每步都生成。</p>',54)])])}const u=a(l,[["render",e]]);export{o as __pageData,u as default};
